import React, { useEffect, useRef, useState } from "react";
import axios from "axios";

const API_BASE_URL =
  process.env.REACT_APP_API_BASE_URL ||
  (process.env.NODE_ENV === "production"
    ? "https://vercel-backend-zeta-green.vercel.app"
    : "http://localhost:5000");

function SupportChatWidget() {
  const [open, setOpen] = useState(false);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [messages, setMessages] = useState([
    {
      role: "assistant",
      content: "Hi! How can I help you today?",
    },
  ]);
  const endRef = useRef(null);

  useEffect(() => {
    if (open && endRef.current) {
      endRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [open, messages]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text || loading) return;

    const userMessage = { role: "user", content: text };
    const nextMessages = [...messages, userMessage];

    setMessages(nextMessages);
    setInput("");
    setLoading(true);

    const history = nextMessages.slice(-8).map((item) => ({
      role: item.role,
      content: item.content,
    }));

    try {
      const token = localStorage.getItem("token");
      const response = await axios.post(
        `${API_BASE_URL}/api/support/chat`,
        { message: text, history },
        {
          headers: token ? { Authorization: `Bearer ${token}` } : {},
        },
      );

      const reply =
        response.data?.reply || "Sorry, I could not find an answer.";

      setMessages((prev) => [...prev, { role: "assistant", content: reply }]);
    } catch (error) {
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content: "Support is unavailable right now. Please try again.",
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="support-chat">
      {open && (
        <div className="support-chat-panel">
          <div className="support-chat-header">
            <div>
              <h4>Support</h4>
              <span>Ask about products, orders, or policies</span>
            </div>
            <button
              type="button"
              className="support-chat-close"
              onClick={() => setOpen(false)}
            >
              Close
            </button>
          </div>

          <div className="support-chat-messages">
            {messages.map((item, index) => (
              <div
                key={`${item.role}-${index}`}
                className={`support-chat-message ${item.role}`}
              >
                {item.content}
              </div>
            ))}
            {loading && (
              <div className="support-chat-message assistant">Typing...</div>
            )}
            <div ref={endRef} />
          </div>

          <div className="support-chat-input">
            <textarea
              rows={2}
              value={input}
              onChange={(event) => setInput(event.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Type your question..."
            />
            <button
              type="button"
              className="btn btn-primary"
              onClick={handleSend}
              disabled={loading}
            >
              Send
            </button>
          </div>
        </div>
      )}

      {!open && (
        <button
          type="button"
          className="support-chat-button"
          onClick={() => setOpen(true)}
        >
          Support
        </button>
      )}
    </div>
  );
}

export default SupportChatWidget;
